// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./Verifier.sol";

contract IdentityAccess {
    /* ═════════ Struct ═════════ */
    struct User {
        bool     isDoctor;
        bytes32  specCommit;   // hash chuyên khoa (chỉ bác sĩ dùng)
        bytes32  hcccd;        // sha256(CCCD‖salt)
        bytes32  hashId;       // Poseidon(hcccd)
        // address  wallet;
    }

    /* ═════════ Events (thêm) ═════════ */
    event Registered(
        bytes32 indexed hashId,
        bytes32 hcccd,
        bytes32 specCommit,
        bool    isDoctor
    );

    /* ═════════ Storage ═════════ */
    mapping(bytes32 => User)           public users;    // key = hashId
    mapping(address => bytes32)        public hashOf;   // addr  → hashId
    address public admin;
    Verifier public verifier;

    constructor(address _verifier) {
        // admin    = msg.sender;
        verifier = Verifier(_verifier);
    }
    // modifier onlyAdmin() { require(msg.sender == admin, "only-admin"); _; }

    /* ═════════ 1) Đăng ký ═════════ */
    /// @param _hashId    Poseidon( sha256(CCCD‖salt) )
    /// @param _hcccd     sha256(CCCD‖salt)
    /// @param _spec      bytes32 commit chuyên khoa (chỉ khi bác sĩ)
    /// @param _asDoctor  true → đăng ký bác sĩ, false → bệnh nhân
    function register(
        bytes32 _hashId,
        bytes32 _hcccd,
        bytes32 _spec,
        bool    _asDoctor
    ) external {
        require(users[_hashId].hashId == 0, "exists");
        users[_hashId] = User(
            _asDoctor,
            _spec,
            _hcccd,
            _hashId
        );
        hashOf[msg.sender] = _hashId;
        //  /* ── emit log để Etherscan hiển thị ── */
        // emit Registered(_hashId, _hcccd, _spec, msg.sender, _asDoctor);
    }

    // /* ═════════ 2) Admin duyệt ═════════ */
    // function approve(bytes32 _hashId) external onlyAdmin {
    //     require(users[_hashId].hashId != 0, "not-reg");
    //     users[_hashId].approved = true;
    // }

    /* ═════════ 3) Getter vai trò ═════════ */
    function isDoctor(address who) public view returns (bool) {
        bytes32 h = hashOf[who];
        return users[h].isDoctor ;
    }
    function isPatient(address who) public view returns (bool) {
        bytes32 h = hashOf[who];
        return !users[h].isDoctor;
    }
    function isAdmin(address who) public view returns (bool) { return who == admin; }
    function specOf(address doctor) external view returns (bytes32) {
        return users[hashOf[doctor]].specCommit;
    }
    
    function getUserByWallet(address wallet) public view returns (
    bytes32 hashId,
    bytes32 specCommit,
    bytes32 hcccd,
    bool    doctorFlag
) {
    bytes32 _hashId = hashOf[wallet];
    User memory u = users[_hashId];
    return (_hashId, u.specCommit, u.hcccd, u.isDoctor);
}

    /* ═════════ 4) zk-Login ═════════ */
 function zkLogin(
    uint256[2] calldata a,
    uint256[2][2] calldata b,
    uint256[2] calldata c,
    uint256        pubHash
) external view returns (bool) {
    // Kiểm tra hashId đã đăng ký của ví này
    if (uint256(hashOf[msg.sender]) != pubHash) {
        return false; // Hoặc revert để báo lỗi bảo mật
    }
    // Kiểm tra proof ZKP hợp lệ
    return verifier.verifyProof(a, b, c, [pubHash]);
}
    // Bạn có thể thêm điều kiện kiểm tra người dùng có tồn tại không (nếu muốn):
    // bytes32 h = bytes32(pubHash);
    // return verifier.verifyProof(a, b, c, [pubHash]) && users[h].wallet != address(0);
}

